insert into public_api_sync_log (
      api_name
    , sync_type
    , status
    , request_count
    , success_count
    , fail_count
    , error_message
    , started_at
    , finished_at
) values (
      #{apiName}
    , #{syncType}
    , #{status}
    , #{requestCount}
    , #{successCount}
    , #{failCount}
    , #{errorMessage}
    , current_timestamp
    , current_timestamp
)
